document.write('<script src="matter-core.min.js"><\/script>');
(function(){
  const FONT_URL='./fonts/ZLabsPixel-subset.woff2';
  const preload=document.createElement('link');
  preload.rel='preload'; preload.as='font'; preload.type='font/woff2'; preload.crossOrigin='anonymous'; preload.href=FONT_URL;
  document.head.appendChild(preload);

  const style=document.createElement('style');
  style.textContent=`@font-face{font-family:"ZLabsPixelCN";src:url("${FONT_URL}") format("woff2");font-style:normal;font-weight:400;font-display:swap}#modeOverlay{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;text-align:center;background:#0a1b32f7;padding:20px;color:#eaffff}.mode-title,.mode-sub,.mode-option,.mode-enter,#overlay h2,#winOverlay h2,#overlay p,#winOverlay p,#loadingOverlay p,.dialog-label,.loading-progress,.loading-note,.screen-caption,.panel small{font-family:"ZLabsPixelCN","Microsoft YaHei",sans-serif!important;font-weight:400!important;letter-spacing:1.5px}.mode-title{font-size:21px;letter-spacing:3px;color:#dffcff}.mode-sub{font-size:10px;color:#7bd6e6}.mode-options{display:flex;flex-direction:column;gap:10px;width:min(78%,240px);margin:4px 0}.mode-option{min-height:50px;border:1px solid #52798d;border-radius:4px;background:#102943;color:#9dbdca;font-size:14px;letter-spacing:1.5px;text-align:center;padding:10px 14px;box-shadow:none}.mode-option b{color:#eaffff;font:400 15px "ZLabsPixelCN","Microsoft YaHei",sans-serif}.mode-option.selected{border-color:#aef8ff;background:#123952;color:#8eeaf2;box-shadow:0 0 14px #43d4fe33}.mode-option.selected b{color:#cfffff}.mode-enter{border:1px solid #c1fcff;border-radius:4px;min-height:44px;padding:10px 22px;background:#8ae5ef;color:#113e57;font-size:13px;margin-top:4px;box-shadow:3px 3px 0 #3c8aab}.end-actions{display:flex;justify-content:center;align-items:center;gap:9px;flex-wrap:nowrap;margin-top:7px;width:100%}.end-actions button{margin-top:0!important;flex:1 1 0;min-width:0!important;max-width:165px;border-radius:4px!important;padding:10px 8px!important;background:#8ae5ef!important;color:#113e57!important;border:1px solid #c1fcff!important;box-shadow:3px 3px 0 #3c8aab!important;font:400 10px "ZLabsPixelCN","Microsoft YaHei",sans-serif!important;letter-spacing:0!important;white-space:nowrap!important}#winOverlay h2{font-size:19px!important;line-height:1.35!important;letter-spacing:.5px!important;white-space:nowrap!important}#overlay h2{font-size:20px!important;line-height:1.35!important}.bigphoto{max-height:40%!important}#loadingOverlay{gap:9px!important;padding:14px!important}.dialog-label{font-size:8px!important;letter-spacing:1.4px!important;white-space:nowrap}.loading-progress{font-family:"ZLabsPixelCN","Microsoft YaHei",sans-serif!important;font-size:12px!important;line-height:1.35!important;font-weight:400!important;letter-spacing:1px!important;text-shadow:none!important;white-space:pre!important}.loading-note{font-size:9px!important;line-height:1.4!important;letter-spacing:.5px!important;white-space:nowrap}.screen-caption,.panel small{letter-spacing:1.2px!important}@media(max-width:420px){#winOverlay h2{font-size:17px!important}.end-actions{gap:7px}.end-actions button{font-size:9px!important;padding:9px 5px!important}#loadingOverlay{gap:7px!important}.dialog-label{font-size:7px!important}.loading-progress{font-size:11px!important}.loading-note{font-size:8px!important}}@media(max-height:560px) and (min-width:600px){#modeOverlay{gap:7px;padding:7px}.mode-title{font-size:14px}.mode-sub{font-size:7px}.mode-options{gap:5px;margin:0}.mode-option{min-height:34px;padding:5px 10px;font-size:9px}.mode-option b{font-size:10px}.mode-enter{min-height:34px;padding:5px 14px;font-size:9px}#loadingOverlay{gap:5px!important;padding:8px!important}.dialog-label{font-size:7px!important}.loading-progress{font-size:9px!important}.loading-note{font-size:7px!important}}`;
  document.head.appendChild(style);

  const stage=document.querySelector('.stage');
  if(!stage)return;
  const mode=document.createElement('div');
  mode.id='modeOverlay';
  mode.setAttribute('role','dialog');
  mode.setAttribute('aria-modal','true');
  mode.innerHTML='<span class="mode-sub">SELECT YOUR MEMORY</span><div class="mode-title">MEMORY MODE</div><div class="mode-sub">选择模式</div><div class="mode-options"><button class="mode-option" data-levels="9"><span>○</span> <b>EASY</b>　简单</button><button class="mode-option selected" data-levels="11"><span>●</span> <b>HARD</b>　困难</button></div><button class="mode-enter" type="button">ENTER MEMORY →</button>';
  stage.appendChild(mode);

  let chosen=11;
  const options=[...mode.querySelectorAll('.mode-option')];
  function select(levels){chosen=levels;options.forEach(btn=>{const active=Number(btn.dataset.levels)===levels;btn.classList.toggle('selected',active);btn.querySelector('span').textContent=active?'●':'○';});}
  options.forEach(btn=>btn.addEventListener('click',()=>select(Number(btn.dataset.levels))));

  function showMode(){try{running=false;cancelAnimationFrame(gameRAF);loadingToken++;}catch(_){ }['overlay','winOverlay','loadingOverlay'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none';});mode.style.display='flex';}
  function begin(){window.__memoryModeLevels=chosen;try{pickLevels=function(){return [...shuffle(RANDOM_POOL.slice()).slice(0,window.__memoryModeLevels-1),FINAL_PHOTO];};const cap=document.querySelector('.screen-caption span:last-child');if(cap)cap.textContent=chosen+' LEVELS';mode.style.display='none';startGame();}catch(e){console.error(e);mode.style.display='flex';}}
  mode.querySelector('.mode-enter').addEventListener('click',begin);

  function makeEndActions(parentId,restartId){const parent=document.getElementById(parentId),restart=document.getElementById(restartId);if(!parent||!restart||parent.querySelector('.end-actions'))return;restart.textContent='PLAY AGAIN / 再来一局';const row=document.createElement('div');row.className='end-actions';parent.insertBefore(row,restart);row.appendChild(restart);const btn=document.createElement('button');btn.type='button';btn.textContent='CHANGE MODE / 切换模式';btn.addEventListener('click',showMode);row.appendChild(btn);}
  makeEndActions('overlay','restart');
  makeEndActions('winOverlay','winRestart');
})();